-- Group 6: Seed the Town
-- Run once after Groups 1-5.
-- Requires at least one existing profile; that profile becomes the initial seed owner.
-- This creates 30 starter communities, categories, topics, memberships, and starter discussions.


do $$
declare
  seed_user uuid;
  c_id uuid;
  cat_id uuid;
begin
  select id into seed_user from public.profiles order by created_at limit 1;
  if seed_user is null then raise exception 'Create at least one user before seeding the town.'; end if;

end $$;

-- Verify the seed counts.
select (select count(*) from public.communities) as communities, (select count(*) from public.community_categories) as categories, (select count(*) from public.topics) as topics, (select count(*) from public.community_memberships where role = 'owner') as seeded_owners, (select count(*) from public.posts) as starter_posts;